import numpy as np
import pandas as pd
import torch

app = FastAPI()

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

class AgentRole(str, Enum):
    INGESTION = "ingestion"
    LOGIC_CORE = "logic_core"
    AUDIT = "audit"

class AgentState(str, Enum):
    IDLE = "idle"
    PROCESSING = "processing"
    VALIDATING = "validating"
    ERROR = "error"
    COMPLETED = "completed"

class TaskInput(BaseModel):
    payload: List[float]
    complexity: int

class AgentLog(BaseModel):
    timestamp: float
    agent_id: str
    role: AgentRole
    message: str
    status: AgentState

class ComputeEngine:
    def __init__(self):
        self.device = torch.device("cpu")

    def process_tensor(self, data: List[float], complexity: int) -> Dict[str, Any]:
        tensor_data = torch.tensor(data, dtype=torch.float32).to(self.device)
        weights = torch.randn(len(data), len(data)).to(self.device)
        result = tensor_data
        for _ in range(complexity):
            result = torch.matmul(weights, result)
            result = torch.relu(result)

        numpy_res = result.detach().cpu().numpy()
        df = pd.DataFrame(numpy_res.reshape(-1, 1), columns=["value"])
        stats = {
            "mean": float(df["value"].mean()),
            "std": float(df["value"].std()),
            "max": float(df["value"].max())
        }
        return {"result_vector": numpy_res.tolist(), "stats": stats}

compute_engine = ComputeEngine()

class Agent:
    def __init__(self, role: AgentRole):
        self.id = str(uuid.uuid4())
        self.role = role
        self.state = AgentState.IDLE
        self.logs: List[AgentLog] = []

    def log(self, message: str):
        entry = AgentLog(
            timestamp=time.time(),
            agent_id=self.id,
            role=self.role,
            message=message,
            status=self.state
        )
        self.logs.append(entry)

class IngestionAgent(Agent):
    def __init__(self):
        super().__init__(AgentRole.INGESTION)

    def validate(self, task: TaskInput) -> bool:
        self.state = AgentState.PROCESSING
        self.log("Starting validation")
        if not task.payload:
            self.state = AgentState.ERROR
            self.log("Empty payload")
            return False
        if len(task.payload) > 10000:
             self.state = AgentState.ERROR
             self.log("Payload too large")
             return False
        self.state = AgentState.IDLE
        self.log("Validation successful")
        return True

class LogicCoreAgent(Agent):
    def __init__(self):
        super().__init__(AgentRole.LOGIC_CORE)

    def execute(self, task: TaskInput) -> Dict[str, Any]:
        self.state = AgentState.PROCESSING
        self.log("Starting compute execution")
        try:
            result = compute_engine.process_tensor(task.payload, task.complexity)
            self.state = AgentState.IDLE
            self.log("Compute execution finished")
            return result
        except Exception as e:
            self.state = AgentState.ERROR
            self.log(f"Compute error: {str(e)}")
            return {}

class AuditAgent(Agent):
    def __init__(self):
        super().__init__(AgentRole.AUDIT)

    def verify(self, result: Dict[str, Any]) -> bool:
        self.state = AgentState.VALIDATING
        self.log("Auditing result integrity")
        if "stats" not in result:
            self.state = AgentState.ERROR
            self.log("Missing stats in result")
            return False
        if np.isnan(result["stats"]["mean"]):
             self.state = AgentState.ERROR
             self.log("NaN detected in output")
             return False
        self.state = AgentState.COMPLETED
        self.log("Audit passed")
        return True

