        self.lock = asyncio.Lock()
        self.results = {}

    async def process_pipeline(self, task: TaskInput, task_id: str):
        async with self.lock:
            self.current_step = 1
            if not ingestor.validate(task):
                self.results[task_id] = {"status": "failed", "reason": "Ingestion failed"}
                return

            self.current_step = 2
