import uvicorn
from fastapi import FastAPI, BackgroundTasks, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field
from typing import List, Dict, Any, Optional
from enum import Enum
import uuid
import time
import asyncio
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F

app = FastAPI()

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

class AgentRole(str, Enum):
    INGESTION = "ingestion"
    LOGIC_CORE = "logic_core"
    AUDIT = "audit"

class AgentState(str, Enum):
    IDLE = "idle"
    PROCESSING = "processing"
    VALIDATING = "validating"
    ERROR = "error"
    COMPLETED = "completed"

class TaskInput(BaseModel):
    input_vector: List[float]
    sequence_length: int = Field(default=10, ge=1, le=100)
    inference_depth: int = Field(default=3, ge=1, le=12)

class AgentLog(BaseModel):
    timestamp: float
    agent_id: str
    role: AgentRole
    message: str
    status: AgentState
    metrics: Optional[Dict[str, float]] = None

class PositionalEncoding(nn.Module):
    def __init__(self, d_model: int, max_len: int = 5000):
        super().__init__()
        position = torch.arange(max_len).unsqueeze(1)
        div_term = torch.exp(torch.arange(0, d_model, 2) * (-np.log(10000.0) / d_model))
        pe = torch.zeros(max_len, 1, d_model)
        pe[:, 0, 0::2] = torch.sin(position * div_term)
        pe[:, 0, 1::2] = torch.cos(position * div_term)
        self.register_buffer('pe', pe)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return x + self.pe[:x.size(0)]

class ReasoningTransformer(nn.Module):
    def __init__(self, feature_dim: int, d_model: int, nhead: int, num_layers: int):
        super().__init__()
        self.feature_projection = nn.Linear(feature_dim, d_model)
        self.pos_encoder = PositionalEncoding(d_model)
        encoder_layer = nn.TransformerEncoderLayer(d_model=d_model, nhead=nhead, dim_feedforward=512, dropout=0.1)
        self.transformer_encoder = nn.TransformerEncoder(encoder_layer, num_layers=num_layers)
        self.reasoning_head = nn.Sequential(
            nn.Linear(d_model, 64),
            nn.ReLU(),
            nn.Linear(64, 1),
            nn.Sigmoid()
        )
        self._init_weights()

    def _init_weights(self):
        for p in self.parameters():
            if p.dim() > 1:
                nn.init.xavier_uniform_(p)

    def forward(self, src: torch.Tensor) -> torch.Tensor:
        src = self.feature_projection(src)
        src = src.unsqueeze(1)
        src = self.pos_encoder(src)
        memory = self.transformer_encoder(src)
        output = self.reasoning_head(memory)
        return output.squeeze()

class ComputeEngine:
    def __init__(self):
        self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        self.model = ReasoningTransformer(feature_dim=1, d_model=64, nhead=4, num_layers=6).to(self.device)
        self.model.eval()

    def run_inference(self, vector: List[float], depth: int) -> Dict[str, Any]:
        tensor_in = torch.tensor(vector, dtype=torch.float32).unsqueeze(-1).to(self.device)

        start_time = time.time()
        with torch.no_grad():
            output_tensor = self.model(tensor_in)

        inference_time = time.time() - start_time

        numpy_out = output_tensor.cpu().numpy()
        confidence_score = float(np.mean(numpy_out)) if numpy_out.ndim > 0 else float(numpy_out)

        df = pd.DataFrame(vector, columns=['input_signal'])
        df['rolling_mean'] = df['input_signal'].rolling(window=3).mean().fillna(0)

        return {
            "model_confidence": confidence_score,
            "inference_time_ms": inference_time * 1000,
            "tensor_shape": str(output_tensor.shape),
            "signal_stats": {
                "mean": float(df['input_signal'].mean()),
                "variance": float(df['input_signal'].var())
            }
        }

engine = ComputeEngine()

class Agent:
    def __init__(self, role: AgentRole):
        self.id = str(uuid.uuid4())
        self.role = role
        self.state = AgentState.IDLE
        self.logs: List[AgentLog] = []

    def log(self, message: str, status: AgentState, metrics: Optional[Dict[str, float]] = None):
        self.state = status
        entry = AgentLog(
            timestamp=time.time(),
            agent_id=self.id,
            role=self.role,
            message=message,
            status=status,
            metrics=metrics
        )
        self.logs.append(entry)

class IngestionAgent(Agent):
    def __init__(self):
        super().__init__(AgentRole.INGESTION)

    def validate_schema(self, task: TaskInput) -> bool:
        self.log("Receiving data packet...", AgentState.PROCESSING)
        if len(task.input_vector) == 0:
            self.log("CRITICAL: Zero length vector", AgentState.ERROR)
            return False

        tensor_check = torch.tensor(task.input_vector)
        if torch.isnan(tensor_check).any():
            self.log("CRITICAL: NaN values detected in tensor", AgentState.ERROR)
            return False

        self.log(f"Schema validated. Sequence Length: {len(task.input_vector)}", AgentState.IDLE)
        return True

class LogicCoreAgent(Agent):
    def __init__(self):
        super().__init__(AgentRole.LOGIC_CORE)

    def execute_reasoning(self, task: TaskInput) -> Dict[str, Any]:
        self.log(f"Loading ReasoningTransformer (Layers: {task.inference_depth})", AgentState.PROCESSING)
        try:
            result = engine.run_inference(task.input_vector, task.inference_depth)
            self.log("Forward pass complete", AgentState.IDLE, {"confidence": result['model_confidence']})
            return result
        except Exception as e:
            self.log(f"Model Inference Failed: {str(e)}", AgentState.ERROR)
            return {}

class AuditAgent(Agent):
    def __init__(self):
        super().__init__(AgentRole.AUDIT)

    def verify_integrity(self, result: Dict[str, Any]) -> bool:
        self.log("Auditing logic output vectors", AgentState.VALIDATING)

        if result.get('model_confidence', 0.0) < 0.01:
            self.log("Rejection: Model confidence below threshold", AgentState.ERROR)
            return False

        if result.get('inference_time_ms', 0) > 2000:
            self.log("Warning: Latency violation detected", AgentState.VALIDATING)

        self.log("Logic Integrity Confirmed", AgentState.COMPLETED)
        return True

ingestor = IngestionAgent()
logic_core = LogicCoreAgent()
auditor = AuditAgent()

agents_registry = {
    ingestor.id: ingestor,
    logic_core.id: logic_core,
    auditor.id: auditor
}

class LogicOrchestrator:
    def __init__(self):
        self.processing_lock = asyncio.Lock()
        self.result_cache = {}

    async def execute_pipeline(self, task: TaskInput, task_id: str):
        async with self.processing_lock:
            if not ingestor.validate_schema(task):
                self.result_cache[task_id] = {"status": "FAILED", "reason": "Ingestion Refusal"}
                return

            model_output = logic_core.execute_reasoning(task)
            if logic_core.state == AgentState.ERROR:
                self.result_cache[task_id] = {"status": "FAILED", "reason": "Model Collapse"}
                return

            if auditor.verify_integrity(model_output):
                self.result_cache[task_id] = {"status": "SUCCESS", "payload": model_output}
            else:
                self.result_cache[task_id] = {"status": "FAILED", "reason": "Audit Rejection"}

orchestrator = LogicOrchestrator()

@app.post("/api/v1/submit")
async def api_submit_task(task: TaskInput, background_tasks: BackgroundTasks):
    task_id = str(uuid.uuid4())
    background_tasks.add_task(orchestrator.execute_pipeline, task, task_id)
    return {"task_id": task_id, "status": "QUEUED"}

@app.get("/api/v1/status")
def api_agent_status():
    return [
        {
            "id": agent.id,
            "role": agent.role,
            "state": agent.state,
            "log_history": agent.logs[-5:] 
        }
        for agent in agents_registry.values()
    ]

