                const inputVector = ref("0.89, 0.12, 0.45, 0.99, 0.23, 0.67");
                const seqLen = ref(10);
                const depth = ref(6);
                const lastResult = ref(null);
                const connectionStatus = ref(true);
                const uptime = ref(0);
                let chartInstance = null;

                const formatTime = (ts) => {
                    const date = new Date(ts * 1000);
                    return `${date.getHours().toString().padStart(2,'0')}:${date.getMinutes().toString().padStart(2,'0')}:${date.getSeconds().toString().padStart(2,'0')}`;
                };

                const getStatusColor = (status) => `status-${status}`;

                const initChart = () => {
                    const ctx = document.getElementById('confidenceChart').getContext('2d');
                    chartInstance = new Chart(ctx, {
                        type: 'doughnut',
                        data: {
                            labels: ['Confidence', 'Uncertainty'],
                            datasets: [{
                                data: [0, 100],
                                backgroundColor: ['#00ff41', '#111'],
                                borderWidth: 0,
                                cutout: '80%'
                            }]
                        },
                        options: {
                            responsive: true,
                            maintainAspectRatio: false,
                            plugins: { legend: { display: false } },
                            animation: { duration: 0 }
                        }
                    });
                };

                const updateArch = () => {
                    const canvas = document.getElementById('archCanvas');
                    const ctx = canvas.getContext('2d');
                    canvas.width = canvas.parentElement.offsetWidth;
                    canvas.height = canvas.parentElement.offsetHeight;

                    ctx.clearRect(0, 0, canvas.width, canvas.height);

                    const nodes = [
                        { id: 'ingestion', x: canvas.width * 0.2, y: canvas.height * 0.5, label: 'INGEST' },
                        { id: 'logic_core', x: canvas.width * 0.5, y: canvas.height * 0.5, label: 'TRANSFORMER' },
                        { id: 'audit', x: canvas.width * 0.8, y: canvas.height * 0.5, label: 'AUDIT' }
                    ];

                    // Draw Connections
                    ctx.strokeStyle = '#1a441a';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(nodes[0].x, nodes[0].y);
                    ctx.lineTo(nodes[2].x, nodes[2].y);
                    ctx.stroke();

                    // Draw Nodes
                    nodes.forEach(node => {
                        const agent = agents.value.find(a => a.role === node.id);
                        const isActive = agent && agent.state !== 'idle' && agent.state !== 'completed';

                        ctx.beginPath();
                        ctx.arc(node.x, node.y, isActive ? 40 : 30, 0, Math.PI * 2);
                        ctx.fillStyle = isActive ? '#003300' : '#0a0a0a';
                        ctx.fill();
                        ctx.strokeStyle = isActive ? '#00ff41' : '#333';
                        ctx.lineWidth = 2;
                        ctx.stroke();

                        if (isActive) {
                            ctx.beginPath();
                            ctx.arc(node.x, node.y, 45, 0, Math.PI * 2);
                            ctx.strokeStyle = `rgba(0, 255, 65, ${Math.random()})`;
                            ctx.stroke();
                        }

                        ctx.fillStyle = isActive ? '#fff' : '#666';
                        ctx.font = '10px monospace';
                        ctx.textAlign = 'center';
                        ctx.fillText(node.label, node.x, node.y + 4);

                        if(agent) {
                            ctx.fillStyle = getStatusColorCode(agent.state);
                            ctx.font = '8px monospace';
                            ctx.fillText(agent.state.toUpperCase(), node.x, node.y + 55);
                        }
                    });
                };

                const getStatusColorCode = (status) => {
                    const colors = {
                        'idle': '#666666',
                        'processing': '#00ffff',
                        'validating': '#ffff00',
                        'error': '#ff0000',
                        'completed': '#00ff41'
                    };
                    return colors[status] || '#666';
                };

                const fetchData = async () => {
                    try {
                        const res = await fetch('');
                        const data = await res.json();
                        agents.value = data;

                        // Merge logs
                        data.forEach(agent => {
                            agent.log_history.forEach(log => {
                                if (!logs.value.find(l => l.timestamp === log.timestamp && l.agent_id === log.agent_id)) {
                                    logs.value.push(log);
                                }
                            });
                        });
                        logs.value.sort((a, b) => b.timestamp - a.timestamp);
                        if(logs.value.length > 100) logs.value = logs.value.slice(0, 100);

                        updateArch();
                    } catch (e) {
                        connectionStatus.value = false;
                    }
                };

                const execute = async () => {
                    processing.value = true;
                    lastResult.value = null;
                    try {
                        const vec = inputVector.value.split(',').map(n => parseFloat(n));
                        const res = await fetch('', {
                            method: 'POST',
                            headers: {'Content-Type': 'application/json'},
                            body: JSON.stringify({
                                input_vector: vec,
                                sequence_length: seqLen.value,
                                inference_depth: depth.value
                            })
                        });
                        const data = await res.json();
                        poll(data.task_id);
                    } catch (e) {
                        processing.value = false;
                    }
                };

                const poll = (id) => {
                    const iv = setInterval(async () => {
                        const res = await fetch(``);
                        const data = await res.json();
                        if (data.status !== 'PROCESSING' && data.status !== 'QUEUED') {
                            clearInterval(iv);
                            lastResult.value = data;
                            processing.value = false;
                            if (data.status === 'SUCCESS' && chartInstance) {
                                const conf = data.payload.model_confidence * 100;
                                chartInstance.data.datasets[0].data = [conf, 100 - conf];
                                chartInstance.update();
                            }
                        }
                    }, 500);
                };

                onMounted(() => {
                    initChart();
                    setInterval(() => { uptime.value++; fetchData(); }, 1000);
                    updateArch();
                    window.addEventListener('resize', updateArch);
                });

                return { logs, agents, processing, inputVector, seqLen, depth, lastResult, connectionStatus, uptime, formatTime, getStatusColor, execute };
            }
        }).mount('#app');
    </script>
